def dfs(graph, start, end, visited=None):
    if visited is None:
        visited = set()

    if start not in graph:
        return None

    visited.add(start)
    if start == end:
        return [start]

    for neighbor in graph[start]:
        if neighbor not in visited:
            path = dfs(graph, neighbor, end, visited)
            if path is not None:
                return [start] + path

    return None

